from duration import parse_duration

valid = {
    "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400,
    "1w2d3h4m5s": 788645, "1:02:03": 3723, "-45s": -45, "0": 0,
    "1.5m": 90, "0.1h": 360, "05m": 300, "1h 30m": 5400,
    "1:30": 90, "1:00:00": 3600, "90:00": 5400, "-1h": -3600,
    "-1:30": -90, "-0s": 0, "0:00": 0, "0.5m30s": 60, "  1s  ": 1,
    "1w": 604800, "0.25m": 15, "1h 30m ": 5400,
}
for s, expected in valid.items():
    got = parse_duration(s)
    assert got == expected, (s, got, expected)
print("valid ok:", len(valid))

invalid = [
    "", "   ", ".5h", "5.h", "30m1h", "1h1h", "1 h", "1h  30m", "1H",
    "1h\t30m", "0.3s", "5", "1.5", "+1h", "--1h", "-", "1:60", "1:5",
    "1:60:00", "1:30:60", "1 h30m", "1h30", "h30m", "1h-30m", "1:2:03",
    "1:30:00:00", "1.5:30", "1:3.0", "1m30m", "1s1m", "1d2w", "1w1d1w",
    "1h 30m 5", "1h,30m", "1 h 30 m", "1h30m5", "1h30m x", "1h  30m",
]
for s in invalid:
    try:
        r = parse_duration(s)
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for %r, got %r" % (s, r))
print("invalid ok:", len(invalid))

for bad in [None, 5, 1.5, b"1h", ["1h"]]:
    try:
        parse_duration(bad)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError for %r" % (bad,))
print("type errors ok")
